import{_ as p,a0 as o,w as d,s as r,I as e,x as i,a1 as n,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 Git 來管理 Git 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Git 來管理 Git 服務器 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Git 來管理 Git 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Git 來管理 Git 服務器 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20190406 Run a server with Git","title":"使用 Git 來管理 Git 服務器","tag":"202001","desc":""},"relativePath":"202001/20190406 Run a server with Git.md","filePath":"[post].md"}'),g={name:"202001/20190406 Run a server with Git.md"};function c(h,s,u,k,b,m){const a=o("Link");return d(),r("div",null,[s[37]||(s[37]=e("h1",{id:"使用-git-來管理-git-服務器",tabindex:"-1"},[i("使用 Git 來管理 Git 服務器 "),e("a",{class:"header-anchor",href:"#使用-git-來管理-git-服務器","aria-label":"Permalink to “使用 Git 來管理 Git 服務器”"},"​")],-1)),s[38]||(s[38]=e("blockquote",null,[e("p",null,"藉助 Gitolite，你可以使用 Git 來管理 Git 服務器。在我們的系列文章中瞭解這些鮮為人知的 Git 用途。")],-1)),s[39]||(s[39]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202001/18/132045yrr1pb9n497tfbiy.png",alt:""})],-1)),e("p",null,[s[1]||(s[1]=i("正如我在系列文章中演示的那樣，",-1)),n(a,{href:"https://git-scm.com/"},{default:t(()=>[...s[0]||(s[0]=[i("Git",-1)])]),_:1}),s[2]||(s[2]=i(" 除了跟蹤源代碼外，還可以做很多事情。信不信由你，Git 甚至可以管理你的 Git 服務器，因此你可以或多或少地使用 Git 本身來運行 Git 服務器。",-1))]),e("p",null,[s[4]||(s[4]=i("當然，這涉及除日常使用 Git 之外的許多組件，其中最重要的是 ",-1)),n(a,{href:"http://gitolite.com"},{default:t(()=>[...s[3]||(s[3]=[i("Gitolite",-1)])]),_:1}),s[5]||(s[5]=i("，該後端應用程序可以管理你使用 Git 的每個細微的配置。Gitolite 的優點在於，由於它使用 Git 作為其前端接口，因此很容易將 Git 服務器管理集成到其他基於 Git 的工作流中。Gitolite 可以精確控制誰可以訪問你服務器上的特定存儲庫以及他們具有哪些權限。你可以使用常規的 Linux 系統工具自行管理此類事務，但是如果有好幾個用户和不止一兩個倉庫，則需要大量的工作。",-1))]),s[40]||(s[40]=e("p",null,"Gitolite 的開發人員做了艱苦的工作，使你可以輕鬆地為許多用户提供對你的 Git 服務器的訪問權，而又不讓他們訪問你的整個環境 —— 而這一切，你可以使用 Git 來完成全部工作。",-1)),e("p",null,[s[7]||(s[7]=i("Gitolite 並",-1)),s[8]||(s[8]=e("strong",null,"不是",-1)),s[9]||(s[9]=i("圖形化的管理員和用户面板。優秀的 ",-1)),n(a,{href:"http://gitea.io"},{default:t(()=>[...s[6]||(s[6]=[i("Gitea",-1)])]),_:1}),s[10]||(s[10]=i(" 項目可提供這種體驗，但是本文重點介紹 Gitolite 的簡單優雅和令人舒適的熟悉感。",-1))]),s[41]||(s[41]=l('<h3 id="安裝-gitolite" tabindex="-1">安裝 Gitolite <a class="header-anchor" href="#安裝-gitolite" aria-label="Permalink to “安裝 Gitolite”">​</a></h3><p>假設你的 Git 服務器運行在 Linux 上，則可以使用包管理器安裝 Gitolite（在 CentOS 和 RHEL 上為 <code>yum</code>，在 Debian 和 Ubuntu 上為 <code>apt</code>，在 OpenSUSE 上為 <code>zypper</code> 等）。例如，在 RHEL 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install gitolite3</span></span></code></pre></div><p>許多發行版的存儲庫提供的仍是舊版本的 Gitolite，但最新版本為版本 3。</p>',4)),e("p",null,[s[12]||(s[12]=i("你必須具有對服務器的無密碼 SSH 訪問權限。如果願意，你可以使用密碼登錄服務器，但是 Gitolite 依賴於 SSH 密鑰，因此必須配置使用密鑰登錄的選項。如果你不知道如何配置服務器以進行無密碼 SSH 訪問，請首先學習如何進行操作（Steve Ovens 的 Ansible 文章的",-1)),n(a,{href:"Setting%20up%20SSH%20key%20authentication"},{default:t(()=>[...s[11]||(s[11]=[i("設置 SSH 密鑰身份驗證",-1)])]),_:1}),s[13]||(s[13]=i("部分對此進行了很好的説明）。這是加強服務器管理的安全以及運行 Gitolite 的重要組成部分。",-1))]),s[42]||(s[42]=l(`<h3 id="配置-git-用户" tabindex="-1">配置 Git 用户 <a class="header-anchor" href="#配置-git-用户" aria-label="Permalink to “配置 Git 用户”">​</a></h3><p>如果沒有 Gitolite，則如果某人請求訪問你在服務器上託管的 Git 存儲庫時，則必須向該人提供用户帳户。Git 提供了一個特殊的外殼，即 <code>git-shell</code>，這是一個僅執行 Git 任務的特別的特定 shell。這可以讓你有個只能通過非常受限的 Shell 環境來過濾訪問你的服務器的用户。</p><p>這個解決方案是一個辦法，但通常意味着用户可以訪問服務器上的所有存儲庫，除非你具有用於組權限的良好模式，並在創建新存儲庫時嚴格遵循這些權限。這種方式還需要在系統級別進行大量手動配置，這通常是隻有特定級別的系統管理員才能做的工作，而不一定是通常負責 Git 存儲庫的人員。</p><p>Gitolite 通過為需要訪問任何存儲庫的每個人指定一個用户名來完全迴避此問題。默認情況下，該用户名是 <code>git</code>，並且由於 Gitolite 的文檔中假定使用的是它，因此在學習該工具時保留它是一個很好的默認設置。對於曾經使用過 GitLab 或 GitHub 或任何其他 Git 託管服務的人來説，這也是一個眾所周知的約定。</p><p>Gitolite 將此用户稱為<strong>託管用户</strong>。在服務器上創建一個帳户以充當託管用户（我習慣使用 <code>git</code>，因為這是慣例）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo adduser --create-home git</span></span></code></pre></div><p>為了控制該 <code>git</code> 用户帳户，該帳户必須具有屬於你的有效 SSH 公鑰。你應該已經進行了設置，因此複製你的公鑰（<strong>而不是你的私鑰</strong>）添加到 <code>git</code> 用户的家目錄中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp ~/.ssh/id_ed25519.pub /home/git/</span></span>
<span class="line"><span>$ sudo chown git:git /home/git/id_ed25519.pub</span></span></code></pre></div><p>如果你的公鑰不以擴展名 <code>.pub</code> 結尾，則 Gitolite 不會使用它，因此請相應地重命名該文件。切換為該用户帳户以運行 Gitolite 的安裝程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su - git</span></span>
<span class="line"><span>$ gitolite setup --pubkey id_ed25519.pub</span></span></code></pre></div><p>安裝腳本運行後，<code>git</code> 的家用户目錄將有一個 <code>repository</code> 目錄，該目錄（目前）包含存儲庫 <code>git-admin.git</code> 和 <code>testing.git</code>。這就是該服務器所需的全部設置，現在請登出 <code>git</code> 用户。</p><h3 id="使用-gitolite" tabindex="-1">使用 Gitolite <a class="header-anchor" href="#使用-gitolite" aria-label="Permalink to “使用 Gitolite”">​</a></h3><p>管理 Gitolite 就是編輯 Git 存儲庫中的文本文件，尤其是 <code>gitolite-admin.git</code> 中的。你不會通過 SSH 進入服務器來進行 Git 管理，並且 Gitolite 也建議你不要這樣嘗試。在 Gitolite 服務器上存儲你和你的用户的存儲庫是個<strong>裸</strong>存儲庫，因此最好不要使用它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone git@example.com:gitolite-admin.git gitolite-admin.git</span></span>
<span class="line"><span>$ cd gitolite-admin.git</span></span>
<span class="line"><span>$ ls -1</span></span>
<span class="line"><span>conf</span></span>
<span class="line"><span>keydir</span></span></code></pre></div><p>該存儲庫中的 <code>conf</code> 目錄包含一個名為 <code>gitolite.conf</code> 的文件。在文本編輯器中打開它，或使用 <code>cat</code> 查看其內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>repo gitolite-admin</span></span>
<span class="line"><span>    RW+     =   id_ed22519</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo testing</span></span>
<span class="line"><span>    RW+     =   @all</span></span></code></pre></div><p>你可能對該配置文件的功能有所瞭解：<code>gitolite-admin</code> 代表此存儲庫，並且 <code>id_ed25519</code> 密鑰的所有者具有讀取、寫入和管理 Git 的權限。換句話説，不是將用户映射到普通的本地 Unix 用户（因為所有用户都使用 <code>git</code> 用户託管用户身份），而是將用户映射到 <code>keydir</code> 目錄中列出的 SSH 密鑰。</p><p><code>testing.git</code> 存儲庫使用特殊組符號為訪問服務器的每個人提供了全部權限。</p><h4 id="添加用户" tabindex="-1">添加用户 <a class="header-anchor" href="#添加用户" aria-label="Permalink to “添加用户”">​</a></h4><p>如果要向 Git 服務器添加一個名為 <code>alice</code> 的用户，Alice 必須向你發送她的 SSH 公鑰。Gitolite 使用文件名的 <code>.pub</code> 擴展名左邊的任何內容作為該 Git 用户的標識符。不要使用默認的密鑰名稱值，而是給密鑰指定一個指示密鑰所有者的名稱。如果用户有多個密鑰（例如，一個用於筆記本電腦，一個用於台式機），則可以使用子目錄來避免文件名衝突。例如，Alice 在筆記本電腦上使用的密鑰可能是默認的 <code>id_rsa.pub</code>，因此將其重命名為<code>alice.pub</code> 或類似名稱（或讓用户根據其計算機上的本地用户帳户來命名密鑰），然後將其放入 <code>gitolite-admin.git/keydir/work/laptop/</code> 目錄中。如果她從她的桌面計算機發送了另一個密鑰，命名為 <code>alice.pub</code>（與上一個相同），然後將其添加到 <code>keydir/home/desktop/</code> 中。另一個密鑰可能放到 <code>keydir/home/desktop/</code> 中，依此類推。Gitolite 遞歸地在 <code>keydir</code> 中搜索與存儲庫“用户”相匹配的 <code>.pub</code> 文件，並將所有匹配項視為相同的身份。</p>`,20)),e("p",null,[s[15]||(s[15]=i("當你將密鑰添加到 ",-1)),s[16]||(s[16]=e("code",null,"keydir",-1)),s[17]||(s[17]=i(" 目錄時，必須將它們提交回服務器。這是一件很容易忘記的事情，這裏有一個使用自動化的 Git 應用程序（例如 ",-1)),n(a,{href:"https://opensource.com/article/19/4/file-sharing-git"},{default:t(()=>[...s[14]||(s[14]=[i("Sparkleshare",-1)])]),_:1}),s[18]||(s[18]=i("）的真正的理由，因此任何更改都將立即提交給你的 Gitolite 管理員。第一次忘記提交和推送，在浪費了三個小時的你和你的用户的故障排除時間之後，你會發現 Gitolite 是使用 Sparkleshare 的完美理由。",-1))]),s[43]||(s[43]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git add keydir</span></span>
<span class="line"><span>$ git commit -m &#39;added alice-laptop-0.pub&#39;</span></span>
<span class="line"><span>$ git push origin HEAD</span></span></code></pre></div><p>默認情況下，Alice 可以訪問 <code>testing.git</code> 目錄，因此她可以使用該目錄測試連接性和功能。</p><h4 id="設置權限" tabindex="-1">設置權限 <a class="header-anchor" href="#設置權限" aria-label="Permalink to “設置權限”">​</a></h4><p>與用户一樣，目錄權限和組也是從你可能習慣的的常規 Unix 工具中抽象出來的（或可從在線信息查找）。在 <code>gitolite-admin.git/conf</code> 目錄中的 <code>gitolite.conf</code> 文件中授予對項目的權限。權限分為四個級別：</p><ul><li><code>R</code> 允許只讀。在存儲庫上具有 <code>R</code> 權限的用户可以克隆它，僅此而已。</li><li><code>RW</code> 允許用户執行分支的快進推送、創建新分支和創建新標籤。對於大多數用户來説，這個基本上就像是一個“普通”的 Git 存儲庫。</li><li><code>RW+</code> 允許可能具有破壞性的 Git 動作。用户可以執行常規的快進推送、回滾推送、變基以及刪除分支和標籤。你可能想要或不希望將其授予項目中的所有貢獻者。</li><li><code>-</code> 明確拒絕訪問存儲庫。這與未在存儲庫的配置中列出的用户相同。</li></ul><p>通過調整 <code>gitolite.conf</code> 來創建一個新的存儲庫或修改現有存儲庫的權限。例如，授予 Alice 權限來管理一個名為 <code>widgets.git</code> 的新存儲庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>repo gitolite-admin</span></span>
<span class="line"><span>    RW+     =   id_ed22519</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo testing</span></span>
<span class="line"><span>    RW+     =   @all</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo widgets</span></span>
<span class="line"><span>    RW+     =   alice</span></span></code></pre></div><p>現在，Alice（也僅有 Alice 一個人）可以克隆該存儲庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[alice]$ git clone git@example.com:widgets.git</span></span>
<span class="line"><span>Cloning into &#39;widgets&#39;...</span></span>
<span class="line"><span>warning: You appear to have cloned an empty repository.</span></span></code></pre></div><p>在第一次推送時，Alice 必須使用 <code>-u</code> 選項將其分支發送到空存儲庫（如同她在任何 Git 主機上做的一樣）。</p><p>為了簡化用户管理，你可以定義存儲庫組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@qtrepo = widgets</span></span>
<span class="line"><span>@qtrepo = games</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo gitolite-admin</span></span>
<span class="line"><span>    RW+     =   id_ed22519</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo testing</span></span>
<span class="line"><span>    RW+     =   @all</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo @qtrepo</span></span>
<span class="line"><span>    RW+     =   alice</span></span></code></pre></div><p>正如你可以創建組存儲庫一樣，你也可以對用户進行分組。默認情況下存在一個用户組：<code>@all</code>。如你所料，它包括所有用户，無一例外。你也可以創建自己的組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@qtrepo = widgets</span></span>
<span class="line"><span>@qtrepo = games</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@developers = alice bob</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo gitolite-admin</span></span>
<span class="line"><span>    RW+     =   id_ed22519</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo testing</span></span>
<span class="line"><span>    RW+     =   @all</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo @qtrepo</span></span>
<span class="line"><span>    RW+     =   @developers</span></span></code></pre></div><p>與添加或修改密鑰文件一樣，對 <code>gitolite.conf</code> 文件的任何更改都必須提交併推送以生效。</p><h3 id="創建存儲庫" tabindex="-1">創建存儲庫 <a class="header-anchor" href="#創建存儲庫" aria-label="Permalink to “創建存儲庫”">​</a></h3><p>默認情況下，Gitolite 假設存儲庫的創建是從上至下進行。例如，有權訪問 Git 服務器的項目經理創建了一個項目存儲庫，並通過 Gitolite 管理倉庫添加了開發人員。</p><p>實際上，你可能更願意向用户授予創建存儲庫的權限。Gitolite 稱這些為“<ruby>野生倉庫（通配倉庫）<rt>wild repos</rt></ruby>”（我不確定這是關於倉庫的形成方式的描述，還是指配置文件所需的通配符）。這是一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@managers = alice bob</span></span>
<span class="line"><span></span></span>
<span class="line"><span>repo foo/CREATOR/[a-z]..*</span></span>
<span class="line"><span>    C   =   @managers</span></span>
<span class="line"><span>    RW+ =   CREATOR</span></span>
<span class="line"><span>    RW  =   WRITERS</span></span>
<span class="line"><span>    R   =   READERS</span></span></code></pre></div><p>第一行定義了一組用户：該組稱為 <code>@managers</code>，其中包含用户 <code>alice</code> 和 <code>bob</code>。下一行設置了通配符允許創建尚不存在的存儲庫，放在名為 <code>foo</code> 的目錄下的創建該存儲庫的用户名的子目錄中。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[alice]$ git clone git@example.com:foo/alice/cool-app.git</span></span>
<span class="line"><span>Cloning into cool-app&#39;...</span></span>
<span class="line"><span>Initialized empty Git repository in /home/git/repositories/foo/alice/cool-app.git</span></span>
<span class="line"><span>warning: You appear to have cloned an empty repository.</span></span></code></pre></div><p>野生倉庫的創建者可以使用一些機制來定義誰可以讀取和寫入其存儲庫，但是他們是有範圍限定的。在大多數情況下，Gitolite 假定由一組特定的用户來管理項目權限。一種解決方案是使用 Git 掛鈎來授予所有用户對 <code>gitolite-admin</code> 的訪問權限，以要求管理者批准將更改合併到 master 分支中。</p><h3 id="瞭解更多" tabindex="-1">瞭解更多 <a class="header-anchor" href="#瞭解更多" aria-label="Permalink to “瞭解更多”">​</a></h3>`,23)),e("p",null,[s[20]||(s[20]=i("Gitolite 具有比此介紹性文章所涵蓋的更多功能，因此請嘗試一下。其",-1)),n(a,{href:"http://gitolite.com/gitolite/quick_install.html"},{default:t(()=>[...s[19]||(s[19]=[i("文檔",-1)])]),_:1}),s[21]||(s[21]=i("非常出色，一旦你通讀了它，就可以自定義 Gitolite 服務器，以向用户提供你喜歡的任何級別的控制。Gitolite 是一種維護成本低、簡單的系統，你可以安裝、設置它，然後基本上就可以將其忘卻。",-1))]),s[44]||(s[44]=e("hr",null,null,-1)),e("p",null,[s[23]||(s[23]=i("via: ",-1)),n(a,{href:"https://opensource.com/article/19/4/server-administration-git"},{default:t(()=>[...s[22]||(s[22]=[i("https://opensource.com/article/19/4/server-administration-git",-1)])]),_:1})]),e("p",null,[s[28]||(s[28]=i("作者：",-1)),n(a,{href:"https://opensource.com/users/seth/users/seth"},{default:t(()=>[...s[24]||(s[24]=[i("Seth Kenlon",-1)])]),_:1}),s[29]||(s[29]=i(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[25]||(s[25]=[i("lujun9972",-1)])]),_:1}),s[30]||(s[30]=i(" 譯者：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[26]||(s[26]=[i("wxy",-1)])]),_:1}),s[31]||(s[31]=i(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[27]||(s[27]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[34]||(s[34]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[32]||(s[32]=[i("LCTT",-1)])]),_:1}),s[35]||(s[35]=i(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...s[33]||(s[33]=[i("Linux中國",-1)])]),_:1}),s[36]||(s[36]=i(" 榮譽推出",-1))])])}const C=p(g,[["render",c]]);export{y as __pageData,C as default};
